/bin/zsh -lc "cat > tb_check.sv <<'EOF'
"'`timescale 1ns/1ps
module tb_check;
  reg clk = 0;
  reg rst_n = 0;
  wire [3:0] gray_out;
  reg [3:0] prev_gray;
  integer hold_count;
  integer transitions;
  integer ones;

  TopModule dut(.clk(clk), .rst_n(rst_n), .gray_out(gray_out));

  always #5 clk = ~clk;

  function integer popcount4(input [3:0] value);
    begin
      popcount4 = value[0] + value[1] + value[2] + value[3];
    end
  endfunction

  initial begin
    prev_gray = 4'"'b0000;
    hold_count = 0;
    transitions = 0;

    #2 rst_n = 0;
    #8 rst_n = 1;

    repeat (34) begin
      @(posedge clk);
      #1;
      if (gray_out === prev_gray) begin
        hold_count = hold_count + 1;
      end else begin
        if (hold_count "'!= 1) begin
          $display("FAIL: gray_out did not hold for two clock cycles before transition at time %0t", $time);
          $finish(1);
        end
        ones = popcount4(gray_out ''^ prev_gray);
        if (ones != 1) begin
          $display("FAIL: gray transition changed %0d bits at time %0t", ones, $time);
          $finish(1);
        end
        hold_count = 0;
        transitions = transitions + 1;
        prev_gray = gray_out;
      end
    end

    $display("PASS: checked %0d transitions", transitions);
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv_check TopModule.sv tb_check.sv && vvp simv_check'

